<?php require_once __DIR__.'/config/config.php';$o=null;$items=[];$history=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT o.*,c.name,c.phone FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.order_code=? AND c.phone=?');$s->execute([trim($_POST['order_code']),trim($_POST['phone'])]);$o=$s->fetch();if($o){$q=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$q->execute([$o['id']]);$items=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM order_status_history WHERE order_id=? ORDER BY created_at');$q->execute([$o['id']]);$history=$q->fetchAll();}}require 'includes/header.php';?><section class="section"><div class="container" style="max-width:760px"><h1 style="font-family:'Playfair Display'">Track Your Order</h1><form method="post" class="admin-card my-4"><?=csrf_field()?><label class="form-label">Order ID</label><input class="form-control mb-3" name="order_code" required><label class="form-label">Phone number</label><input class="form-control mb-3" name="phone" required><button class="btn btn-gold">Track Order</button></form><?php if($_SERVER['REQUEST_METHOD']==='POST'&&!$o):?><p class="text-danger">No matching order found. Check your order ID and phone number.</p><?php endif;?><?php if($o):?><div class="admin-card"><h4><?=e($o['order_code'])?></h4><p><?=e($o['name'])?> · <?=money($o['total'])?></p><h5>Status: <?=e($o['status'])?></h5><ul><?php foreach($history as $h):?><li><?=e($h['status'])?> — <?=e($h['created_at'])?> <?=e($h['note'])?></li><?php endforeach;?></ul><h6>Items</h6><?php foreach($items as $i):?><p><?=e($i['product_name'])?> × <?=$i['quantity']?></p><?php endforeach;?></div><?php endif;?></div></section><?php require 'includes/footer.php';?>